            ["TDP boost"] = "TDP-Boost",
            ["Test versions"] = "Testversionen",
            ["That is what makes the extra controller features possible."] = "Erst dadurch sind die zus\u00E4tzlichen Controller-Funktionen m\u00F6glich.",
            ["That key was rejected."] = "Der Key wurde abgelehnt.",
            ["The MSI button does not open the widget."] = "Die MSI-Taste \u00F6ffnet das Widget nicht.",
            ["The charge limit, the fan curve and the controller mode can only be reset by ClawTweaks. Install it again to restore them, then come back here. You can still uninstall Center."] = "Ladelimit, L\u00FCfterkurve und Controller-Modus kann nur ClawTweaks zur\u00FCcksetzen. Installiere es erneut, setze zur\u00FCck und komm hierher zur\u00FCck. Center l\u00E4sst sich trotzdem deinstallieren.",
            ["The controller did not confirm \u2014 check it before you unplug."] = "Der Controller hat nicht best\u00E4tigt \u2014 pr\u00FCfe ihn, bevor du abziehst.",
            ["The device can be restored"] = "Das Ger\u00E4t l\u00E4sst sich zur\u00FCcksetzen",
            ["The helper did not confirm in time."] = "Der Helper hat nicht rechtzeitig best\u00E4tigt.",
            ["The helper hops to that slot; it cannot read the position itself."] = "Der Helper springt dorthin; auslesen kann er die Position nicht.",
            ["The helper is not answering"] = "Der Helper antwortet nicht",
            ["The last step removes Center and always works."] = "Der letzte Schritt entfernt Center und geht immer.",
            ["The library comes back when the game ends."] = "Die Bibliothek kommt nach Spielende zur\u00FCck.",
            ["The native controller must be clean before the virtual controller mode can work. In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "Der native Controller muss sauber sein, bevor der virtuelle Controller-Modus funktioniert. Im virtuellen Modus wird der physische Pad versteckt und ein virtueller VIIPER-Controller ist aktiv; im Hardware-Modus wird der physische Pad direkt benutzt.",
            ["The newest changes, least tested"] = "Die neuesten \u00C4nderungen, am wenigsten getestet",
            ["The old helper exited on its own."] = "Der alte Helper hat sich selbst beendet.",
            ["The old version's uninstaller is running \u2014 confirm its prompt. This notice disappears once it's gone."] = "Die Deinstallation der alten Version l\u00E4uft \u2014 best\u00E4tige ihre Abfrage. Der Hinweis verschwindet, sobald sie weg ist.",
            ["The package could not be removed. Close the Game Bar and try again, or remove ClawTweaks from Settings \u2192 Apps."] = "Das Paket lie\u00DF sich nicht entfernen. Schlie\u00DFe die Game Bar und versuche es erneut, oder entferne ClawTweaks \u00FCber Einstellungen \u2192 Apps.",
            ["The package family conflicted with this update. Clearing it and retrying once\u2026"] = "Die Paketfamilie stand diesem Update im Weg. Sie wird geleert und einmal erneut versucht\u2026",
            ["The reset did not finish."] = "Das Zur\u00FCcksetzen ist nicht durchgelaufen.",
            ["The signing certificate uses Windows' own prompt, once per device."] = "Das Zertifikat nutzt Windows' eigene Abfrage, einmal pro Ger\u00E4t.",
            ["The widget shows what the helper does; it changes nothing by itself."] = "Das Widget zeigt, was der Helper tut; es \u00E4ndert selbst nichts.",
            ["The wiki page could not be read. Open it in a browser."] = "Die Wiki-Seite lie\u00DF sich nicht lesen. \u00D6ffne sie im Browser.",
            ["These install kernel drivers. Without the restart everything looks installed and the virtual controller silently does not work."] = "Diese installieren Kerneltreiber. Ohne Neustart sieht alles installiert aus und der virtuelle Controller funktioniert stillschweigend nicht.",
            ["This Setup build is outdated"] = "Dieser Setup-Build ist veraltet",
            ["This build can't be installed"] = "Dieser Build l\u00E4sst sich nicht installieren",
            ["This installs an OLDER version than the one installed."] = "Das installiert eine \u00C4LTERE Version als die installierte.",
            ["This is a scaffold build without a bundled package, so there's nothing to install here. In a real setup bundle the .msix and .cer sit next to this exe."] = "Das ist ein Ger\u00FCst-Build ohne mitgeliefertes Paket, hier gibt es also nichts zu installieren. In einem echten Setup-B\u00FCndel liegen .msix und .cer neben dieser exe.",
            ["This puts the device back and clears your ClawTweaks settings:"] = "Das setzt das Ger\u00E4t zur\u00FCck und l\u00F6scht deine ClawTweaks-Einstellungen:",
            ["This removes ClawTweaks Center and closes it."] = "Das entfernt ClawTweaks Center und schlie\u00DFt es.",
            ["This removes the ClawTweaks app from Windows."] = "Das entfernt die ClawTweaks-App aus Windows.",
            ["This resets ALL ClawTweaks settings to a clean state:"] = "Das setzt ALLE ClawTweaks-Einstellungen zur\u00FCck:",
            ["This takes a moment."] = "Das dauert einen Moment.",
            ["This version can't be installed"] = "Diese Version l\u00E4sst sich nicht installieren",
            ["This version is already installed. Open it from the Start Menu or the ClawTweaks Game Bar widget instead of running this Setup file again."] = "Diese Version ist bereits installiert. \u00D6ffne sie \u00FCber das Startmen\u00FC oder das ClawTweaks-Widget in der Game Bar, statt diese Setup-Datei erneut auszuf\u00FChren.",
            ["Timed out"] = "Zeit abgelaufen",
            ["To tray"] = "Taskleiste",
            ["Transition to new Center App - Uninstall the old version"] = "Umstieg auf das neue Center \u2014 alte Version deinstallieren",
            ["Trusts the signing certificate, installs the app package, opens the Game Bar and waits for the helper. Safe to run again on an update."] = "Vertraut dem Signaturzertifikat, installiert das App-Paket, \u00F6ffnet die Game Bar und wartet auf den Helper. Bei einem Update gefahrlos wiederholbar.",
            ["Turn MSI Center M back on"] = "MSI Center M wieder einschalten",
            ["Turn it on in Onboarding. It switches itself back if no pad appears."] = "Im Onboarding einschalten. Erscheint kein Pad, schaltet er sich zur\u00FCck.",
            ["Turn it on under Settings to show covers only."] = "In den Einstellungen einschalten, um nur Cover zu zeigen.",
            ["Turn on"] = "Einschalten",
            ["Turn on Settings \u2192 Start in the library to open here every time."] = "Schalte Einstellungen \u2192 In der Bibliothek starten ein, um immer hier zu landen.",
            ["Turning MSI Center M back on\u2026"] = "Schaltet MSI Center M wieder ein\u2026",
