            ["Update failed \u2014 see the log for details. Try again, or run as Administrator."] = "Update fehlgeschlagen \u2014 Details stehen im Log. Erneut versuchen oder als Administrator ausf\u00FChren.",
            ["Updates cost no prompt \u2014 the task does not carry a version number."] = "Updates kosten keine Abfrage \u2014 die Aufgabe tr\u00E4gt keine Versionsnummer.",
            ["Updating..."] = "Aktualisiere...",
            ["Use Uninstall ClawTweaks here in Center instead."] = "Nimm stattdessen hier in Center \u201EUninstall ClawTweaks\u201C.",
            ["Verifying the virtual pad\u2026"] = "Virtueller Pad wird gepr\u00FCft\u2026",
            ["Vibration"] = "Vibration",
