            ["Yes, uninstall ClawTweaks"] = "Ja, ClawTweaks deinstallieren",
            ["Your Claw's own gamepad is hidden and replaced by a virtual one."] = "Der echte Controller der Claw wird versteckt und durch einen virtuellen ersetzt.",
            ["Your ClawTweaks library"] = "Deine ClawTweaks-Bibliothek",
