            ["Favorites"] = "\uC990\uACA8\uCC3E\uAE30",
            ["Final clean-up and check. MSI Center M is handled here (after installation) because it fights ClawTweaks for the controller and LED."] = "\uB9C8\uC9C0\uB9C9 \uC815\uB9AC \uBC0F \uD655\uC778\uC785\uB2C8\uB2E4. MSI Center M\uC740 \uCEE8\uD2B8\uB864\uB7EC\uC640 LED\uB97C \uB450\uACE0 ClawTweaks\uC640 \uCDA9\uB3CC\uD558\uBBC0\uB85C \uC124\uCE58 \uD6C4 \uC5EC\uAE30\uC11C \uCC98\uB9AC\uD569\uB2C8\uB2E4.",
            ["Final controller check"] = "\uB9C8\uC9C0\uB9C9 \uCEE8\uD2B8\uB864\uB7EC \uD655\uC778",
