            ["Refresh rate"] = "\uC8FC\uC0AC\uC728",
            ["Refresh status"] = "\uC0C1\uD0DC \uC0C8\uB85C \uACE0\uCE68",
            ["Relaunching from install location..."] = "\uC124\uCE58 \uC704\uCE58\uC5D0\uC11C \uB2E4\uC2DC \uC2DC\uC791...",
            ["Remove from Favorites"] = "\uC990\uACA8\uCC3E\uAE30 \uD574\uC81C",
            ["Remove from library"] = "\uB77C\uC774\uBE0C\uB7EC\uB9AC\uC5D0\uC11C \uC81C\uAC70",
            ["Remove the old version"] = "\uC774\uC804 \uBC84\uC804 \uC81C\uAC70",
            ["Removes the app, its background helper and its scheduled task."] = "\uC571\uACFC \uBC31\uADF8\uB77C\uC6B4\uB4DC \uD5EC\uD37C, \uC608\uC57D \uC791\uC5C5\uC744 \uC81C\uAC70\uD569\uB2C8\uB2E4.",
            ["Removes this app and closes it."] = "\uC774 \uC571\uC744 \uC81C\uAC70\uD558\uACE0 \uB2EB\uC2B5\uB2C8\uB2E4.",
            ["Removing Center\u2026"] = "Center \uC81C\uAC70 \uC911\u2026",
            ["Removing ClawTweaks\u2026"] = "ClawTweaks \uC81C\uAC70 \uC911\u2026",
            ["Removing it needs administrator rights. ClawTweaks Center never asks for those \u2014 the button below hands the job to Windows' own uninstaller."] = "\uC81C\uAC70\uD558\uB824\uBA74 \uAD00\uB9AC\uC790 \uAD8C\uD55C\uC774 \uD544\uC694\uD569\uB2C8\uB2E4. ClawTweaks Center\uB294 \uC808\uB300 \uC694\uAD6C\uD558\uC9C0 \uC54A\uC73C\uBA70, \uC544\uB798 \uBC84\uD2BC\uC774 Windows \uC81C\uAC70 \uD504\uB85C\uADF8\uB7A8\uC5D0 \uB118\uAE41\uB2C8\uB2E4.",
            ["Removing leftover helper\u2026"] = "\uB0A8\uC740 \uD5EC\uD37C \uC81C\uAC70 \uC911\u2026",
            ["Renaming looks for new cover art."] = "\uC774\uB984\uC744 \uBC14\uAFB8\uBA74 \uCEE4\uBC84\uB97C \uB2E4\uC2DC \uCC3E\uC2B5\uB2C8\uB2E4.",
            ["Required tools"] = "\uD544\uC694\uD55C \uB3C4\uAD6C",
            ["Required tools (HidHide, RTSS, usbip, PawnIO) already installed."] = "\uD544\uC694\uD55C \uB3C4\uAD6C(HidHide, RTSS, usbip, PawnIO)\uAC00 \uC774\uBBF8 \uC124\uCE58\uB428.",
            ["Requirements"] = "\uC694\uAD6C \uC0AC\uD56D",
            ["Rescan"] = "\uB2E4\uC2DC \uAC80\uC0C9",
            ["Reset complete"] = "\uCD08\uAE30\uD654 \uC644\uB8CC",
            ["Reset failed"] = "\uCD08\uAE30\uD654 \uC2E4\uD328",
            ["Reset the app, or back up your profiles."] = "\uC571\uC744 \uCD08\uAE30\uD654\uD558\uAC70\uB098 \uD504\uB85C\uD544\uC744 \uBC31\uC5C5\uD569\uB2C8\uB2E4.",
            ["Resetting all ClawTweaks settings\u2026"] = "\uBAA8\uB4E0 ClawTweaks \uC124\uC815\uC744 \uCD08\uAE30\uD654\uD558\uB294 \uC911\u2026",
            ["Restart"] = "\uB2E4\uC2DC \uC2DC\uC791",
            ["Restore"] = "\uB418\uB3CC\uB9AC\uAE30",
            ["Restore Backup"] = "\uBC31\uC5C5 \uBCF5\uC6D0",
            ["Restore Backup takes a safety copy before it writes."] = "Restore Backup\uC740 \uC4F0\uAE30 \uC804\uC5D0 \uC548\uC804 \uBCF5\uC0AC\uBCF8\uC744 \uB9CC\uB4ED\uB2C8\uB2E4.",
            ["Restore complete"] = "\uBCF5\uC6D0 \uC644\uB8CC",
            ["Restore failed"] = "\uBCF5\uC6D0 \uC2E4\uD328",
            ["Restore the device"] = "\uAE30\uAE30 \uB418\uB3CC\uB9AC\uAE30",
            ["Restore the device and remove everything."] = "\uAE30\uAE30\uB97C \uB418\uB3CC\uB9AC\uACE0 \uBAA8\uB450 \uC81C\uAC70\uD569\uB2C8\uB2E4.",
            ["Restore the device first"] = "\uBA3C\uC800 \uAE30\uAE30\uB97C \uB418\uB3CC\uB9AC\uC138\uC694",
            ["Restore this backup?"] = "\uC774 \uBC31\uC5C5\uC744 \uBCF5\uC6D0\uD560\uAE4C\uC694?",
            ["Restoring the hardware\u2026"] = "\uD558\uB4DC\uC6E8\uC5B4\uB97C \uB418\uB3CC\uB9AC\uB294 \uC911\u2026",
            ["Right stick"] = "\uC624\uB978\uCABD \uC2A4\uD2F1",
            ["Right trigger"] = "\uC624\uB978\uCABD \uD2B8\uB9AC\uAC70",
            ["Route"] = "\uACBD\uB85C",
            ["Run"] = "\uC2E4\uD589",
            ["Run in background"] = "\uBC31\uADF8\uB77C\uC6B4\uB4DC \uC2E4\uD589",
            ["Running \u2014 it can fight ClawTweaks for the controller and LED. You'll be guided to deactivate it after the app is installed."] = "\uC2E4\uD589 \uC911 \u2014 \uCEE8\uD2B8\uB864\uB7EC\uC640 LED\uB97C \uB450\uACE0 ClawTweaks\uC640 \uCDA9\uB3CC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC124\uCE58 \uD6C4 \uBE44\uD65C\uC131\uD654 \uBC29\uBC95\uC744 \uC548\uB0B4\uD569\uB2C8\uB2E4.",
            ["Running. Press \u24B6 to close it now. For a permanent fix, uninstall it from Windows Settings \u203A Apps and reinstall the latest version if you still need it."] = "\uC2E4\uD589 \uC911\uC785\uB2C8\uB2E4. \u24B6 \uB97C \uB204\uB974\uBA74 \uC9C0\uAE08 \uB2EB\uC2B5\uB2C8\uB2E4. \uC644\uC804\uD788 \uC5C6\uC560\uB824\uBA74 Windows \uC124\uC815 \u203A \uC571\uC5D0\uC11C \uC81C\uAC70\uD558\uACE0 \uD544\uC694\uD558\uBA74 \uCD5C\uC2E0 \uBC84\uC804\uC744 \uB2E4\uC2DC \uC124\uCE58\uD558\uC138\uC694.",
            ["Save"] = "\uC800\uC7A5",
            ["Save all your profiles and settings into a single ZIP you can restore later."] = "\uBAA8\uB4E0 \uD504\uB85C\uD544\uACFC \uC124\uC815\uC744 \uB098\uC911\uC5D0 \uBCF5\uC6D0\uD560 \uC218 \uC788\uB294 ZIP \uD558\uB098\uB85C \uC800\uC7A5\uD569\uB2C8\uB2E4.",
            ["Saves all your profiles and settings into a single ZIP. The Game Bar is briefly closed so the widget's data can be copied \u2014 reopen it (Win+G) afterwards."] = "\uBAA8\uB4E0 \uD504\uB85C\uD544\uACFC \uC124\uC815\uC744 \uD558\uB098\uC758 ZIP\uC73C\uB85C \uC800\uC7A5\uD569\uB2C8\uB2E4. \uC704\uC82F \uB370\uC774\uD130\uB97C \uBCF5\uC0AC\uD558\uAE30 \uC704\uD574 Game Bar\uAC00 \uC7A0\uC2DC \uB2EB\uD788\uBBC0\uB85C \uB098\uC911\uC5D0 Win+G\uB85C \uB2E4\uC2DC \uC5EC\uC138\uC694.",
            ["Saves your session to disk."] = "\uC138\uC158\uC744 \uB514\uC2A4\uD06C\uC5D0 \uC800\uC7A5\uD569\uB2C8\uB2E4.",
            ["Search"] = "\uAC80\uC0C9",
            ["Search SteamGridDB for a different cover"] = "SteamGridDB\uC5D0\uC11C \uB2E4\uB978 \uCEE4\uBC84 \uCC3E\uAE30",
            ["Searching\u2026"] = "\uAC80\uC0C9 \uC911\u2026",
            ["Select"] = "\uC120\uD0DD",
            ["Set a SteamGridDB key in Settings first"] = "\uBA3C\uC800 \uC124\uC815\uC5D0\uC11C SteamGridDB \uD0A4\uB97C \uC785\uB825\uD558\uC138\uC694",
            ["Set as cover"] = "\uCEE4\uBC84\uB85C \uC124\uC815",
            ["Set the library as the screen Center opens on in Library Settings."] = "Library Settings\uC5D0\uC11C \uB77C\uC774\uBE0C\uB7EC\uB9AC\uB97C \uC2DC\uC791 \uD654\uBA74\uC73C\uB85C \uC9C0\uC815\uD558\uC138\uC694.",
            ["Set up Center M, controller and Game Bar."] = "Center M, \uCEE8\uD2B8\uB864\uB7EC, Game Bar\uB97C \uC124\uC815\uD569\uB2C8\uB2E4.",
            ["Set. Covers are downloaded for games with none."] = "\uC124\uC815\uB428. \uC5C6\uB294 \uCEE4\uBC84\uB97C \uB0B4\uB824\uBC1B\uC2B5\uB2C8\uB2E4.",
            ["Setting cover\u2026"] = "\uCEE4\uBC84 \uC801\uC6A9 \uC911\u2026",
            ["Settings"] = "\uC124\uC815",
            ["Settings reset."] = "\uC124\uC815\uC744 \uCD08\uAE30\uD654\uD588\uC2B5\uB2C8\uB2E4.",
            ["Show the certificate in Explorer"] = "\uD0D0\uC0C9\uAE30\uC5D0\uC11C \uC778\uC99D\uC11C \uBCF4\uAE30",
            ["Shows your installed Steam, Xbox and Epic games."] = "\uC124\uCE58\uB41C Steam, Xbox, Epic \uAC8C\uC784\uC744 \uBCF4\uC5EC\uC90D\uB2C8\uB2E4.",
            ["Shut down"] = "\uC885\uB8CC",
            ["Signing certificate"] = "\uC11C\uBA85 \uC778\uC99D\uC11C",
            ["Some hardware commands could not be sent."] = "\uC77C\uBD80 \uD558\uB4DC\uC6E8\uC5B4 \uBA85\uB839\uC744 \uBCF4\uB0B4\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4.",
            ["Square ROM art"] = "\uC815\uC0AC\uAC01\uD615 ROM \uC544\uD2B8",
            ["Start"] = "\uC2DC\uC791",
            ["Start Center with ClawTweaks"] = "ClawTweaks\uC640 \uD568\uAED8 \uC2DC\uC791",
            ["Start in the library"] = "\uB77C\uC774\uBE0C\uB7EC\uB9AC\uB85C \uC2DC\uC791",
            ["Start menu, desktop and startup"] = "\uC2DC\uC791 \uBA54\uB274, \uBC14\uD0D5 \uD654\uBA74, \uC2DC\uC791 \uD504\uB85C\uADF8\uB7A8",
            ["Started from Windows"] = "Windows\uC5D0\uC11C \uC2DC\uC791\uB428",
            ["Starting\u2026"] = "\uC2DC\uC791 \uC911\u2026",
            ["Status"] = "\uC0C1\uD0DC",
            ["Stay open"] = "\uC5F4\uC5B4 \uB450\uAE30",
            ["Steam Xbox filter driver"] = "Steam Xbox \uD544\uD130 \uB4DC\uB77C\uC774\uBC84",
            ["Steam asks you where to put it."] = "Steam\uC774 \uC124\uCE58 \uC704\uCE58\uB97C \uBB3B\uC2B5\uB2C8\uB2E4.",
            ["Steam cover art is found automatically."] = "Steam \uCEE4\uBC84\uB294 \uC790\uB3D9\uC73C\uB85C \uCC3E\uC2B5\uB2C8\uB2E4.",
            ["Steam has taken over. Rescan the library when it is done."] = "Steam\uC774 \uC774\uC5B4\uC11C \uCC98\uB9AC\uD569\uB2C8\uB2E4. \uB05D\uB098\uBA74 \uB77C\uC774\uBE0C\uB7EC\uB9AC\uB97C \uB2E4\uC2DC \uAC80\uC0C9\uD558\uC138\uC694.",
            ["SteamGridDB key"] = "SteamGridDB \uD0A4",
            ["Step 1 has not run. After this, nothing on the device can switch the charge limit off or hand the fan back to firmware."] = "1\uB2E8\uACC4\uB97C \uC544\uC9C1 \uC2E4\uD589\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uC774\uD6C4\uC5D0\uB294 \uAE30\uAE30\uC5D0\uC11C \uCDA9\uC804 \uC81C\uD55C\uC744 \uB044\uAC70\uB098 \uD32C\uC744 \uD38C\uC6E8\uC5B4\uC5D0 \uB118\uAE38 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["Step 1 puts the charge limit, the fan and the controller back."] = "1\uB2E8\uACC4\uAC00 \uCDA9\uC804 \uC81C\uD55C\uACFC \uD32C, \uCEE8\uD2B8\uB864\uB7EC\uB97C \uB418\uB3CC\uB9BD\uB2C8\uB2E4.",
            ["Stick deadzone"] = "\uC2A4\uD2F1 \uB370\uB4DC\uC874",
            ["System"] = "\uC2DC\uC2A4\uD15C",
            ["System language"] = "\uC2DC\uC2A4\uD15C \uC5B8\uC5B4",
            ["TDP boost"] = "TDP \uBD80\uC2A4\uD2B8",
            ["Test versions"] = "\uD14C\uC2A4\uD2B8 \uBC84\uC804",
            ["That is what makes the extra controller features possible."] = "\uADF8\uB35C\uBD84\uC5D0 \uCD94\uAC00 \uCEE8\uD2B8\uB864\uB7EC \uAE30\uB2A5\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
            ["That key was rejected."] = "\uD0A4\uAC00 \uAC70\uBD80\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
            ["The MSI button does not open the widget."] = "MSI \uBC84\uD2BC\uC744 \uB20C\uB7EC\uB3C4 \uC704\uC82F\uC774 \uC5F4\uB9AC\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
            ["The charge limit, the fan curve and the controller mode can only be reset by ClawTweaks. Install it again to restore them, then come back here. You can still uninstall Center."] = "\uCDA9\uC804 \uC81C\uD55C, \uD32C \uCEE4\uBE0C, \uCEE8\uD2B8\uB864\uB7EC \uBAA8\uB4DC\uB294 ClawTweaks\uB9CC \uB418\uB3CC\uB9B4 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uC124\uCE58\uD55C \uB4A4 \uC5EC\uAE30\uB85C \uB3CC\uC544\uC624\uC138\uC694. Center\uB294 \uADF8\uB798\uB3C4 \uC81C\uAC70\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
            ["The controller did not confirm \u2014 check it before you unplug."] = "\uCEE8\uD2B8\uB864\uB7EC\uAC00 \uD655\uC778\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uBD84\uB9AC\uD558\uAE30 \uC804\uC5D0 \uD655\uC778\uD558\uC138\uC694.",
            ["The device can be restored"] = "\uAE30\uAE30\uB97C \uB418\uB3CC\uB9B4 \uC218 \uC788\uC2B5\uB2C8\uB2E4",
            ["The helper did not confirm in time."] = "\uD5EC\uD37C\uAC00 \uC81C\uB54C \uD655\uC778\uD558\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.",
            ["The helper hops to that slot; it cannot read the position itself."] = "\uD5EC\uD37C\uB294 \uADF8 \uC704\uCE58\uB85C \uC774\uB3D9\uD569\uB2C8\uB2E4. \uC704\uCE58\uB97C \uC9C1\uC811 \uC77D\uC744 \uC218\uB294 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["The helper is not answering"] = "\uD5EC\uD37C\uAC00 \uC751\uB2F5\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4",
            ["The last step removes Center and always works."] = "\uB9C8\uC9C0\uB9C9 \uB2E8\uACC4\uB294 Center\uB97C \uC81C\uAC70\uD558\uBA70 \uD56D\uC0C1 \uC2E4\uD589\uB429\uB2C8\uB2E4.",
            ["The library comes back when the game ends."] = "\uAC8C\uC784\uC774 \uB05D\uB098\uBA74 \uB77C\uC774\uBE0C\uB7EC\uB9AC\uB85C \uB3CC\uC544\uC635\uB2C8\uB2E4.",
            ["The native controller must be clean before the virtual controller mode can work. In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "\uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC \uBAA8\uB4DC\uAC00 \uB3D9\uC791\uD558\uB824\uBA74 \uAE30\uBCF8 \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uAE68\uB057\uD574\uC57C \uD569\uB2C8\uB2E4. \uAC00\uC0C1 \uBAA8\uB4DC\uC5D0\uC11C\uB294 \uBB3C\uB9AC \uD328\uB4DC\uAC00 \uC228\uACA8\uC9C0\uACE0 VIIPER \uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uD65C\uC131\uD654\uB418\uBA70, \uD558\uB4DC\uC6E8\uC5B4 \uBAA8\uB4DC\uC5D0\uC11C\uB294 \uBB3C\uB9AC \uD328\uB4DC\uB97C \uC9C1\uC811 \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
            ["The newest changes, least tested"] = "\uAC00\uC7A5 \uC0C8\uB85C\uC6B4 \uBCC0\uACBD, \uAC00\uC7A5 \uC801\uAC8C \uAC80\uC99D\uB428",
            ["The old helper exited on its own."] = "\uC774\uC804 \uD5EC\uD37C\uAC00 \uC2A4\uC2A4\uB85C \uC885\uB8CC\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
            ["The old version's uninstaller is running \u2014 confirm its prompt. This notice disappears once it's gone."] = "\uC774\uC804 \uBC84\uC804\uC758 \uC81C\uAC70 \uD504\uB85C\uADF8\uB7A8\uC774 \uC2E4\uD589 \uC911\uC785\uB2C8\uB2E4 \u2014 \uD45C\uC2DC\uB418\uB294 \uD655\uC778\uC744 \uB20C\uB7EC \uC8FC\uC138\uC694. \uC81C\uAC70\uB418\uBA74 \uC774 \uC548\uB0B4\uB294 \uC0AC\uB77C\uC9D1\uB2C8\uB2E4.",
            ["The package could not be removed. Close the Game Bar and try again, or remove ClawTweaks from Settings \u2192 Apps."] = "\uD328\uD0A4\uC9C0\uB97C \uC81C\uAC70\uD558\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4. \uAC8C\uC784 \uBC14\uB97C \uB2EB\uACE0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uAC70\uB098, \uC124\uC815 \u2192 \uC571\uC5D0\uC11C ClawTweaks\uB97C \uC81C\uAC70\uD558\uC138\uC694.",
            ["The package family conflicted with this update. Clearing it and retrying once\u2026"] = "\uD328\uD0A4\uC9C0 \uC81C\uD488\uAD70\uC774 \uC774 \uC5C5\uB370\uC774\uD2B8\uC640 \uCDA9\uB3CC\uD588\uC2B5\uB2C8\uB2E4. \uC815\uB9AC\uD55C \uB4A4 \uD55C \uBC88 \uB2E4\uC2DC \uC2DC\uB3C4\uD569\uB2C8\uB2E4\u2026",
            ["The reset did not finish."] = "\uCD08\uAE30\uD654\uAC00 \uB05D\uB098\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.",
            ["The signing certificate uses Windows' own prompt, once per device."] = "\uC11C\uBA85 \uC778\uC99D\uC11C\uB294 Windows \uC790\uCCB4 \uCC3D\uC744 \uC4F0\uBA70, \uAE30\uAE30\uB2F9 \uD55C \uBC88\uC785\uB2C8\uB2E4.",
            ["The widget shows what the helper does; it changes nothing by itself."] = "\uC704\uC82F\uC740 \uD5EC\uD37C\uAC00 \uD558\uB294 \uC77C\uC744 \uBCF4\uC5EC\uC904 \uBFD0, \uC2A4\uC2A4\uB85C \uBC14\uAFB8\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
            ["The wiki page could not be read. Open it in a browser."] = "\uC704\uD0A4 \uBB38\uC11C\uB97C \uC77D\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4. \uBE0C\uB77C\uC6B0\uC800\uC5D0\uC11C \uC5F4\uC5B4 \uBCF4\uC138\uC694.",
            ["These install kernel drivers. Without the restart everything looks installed and the virtual controller silently does not work."] = "\uC774\uB4E4\uC740 \uCEE4\uB110 \uB4DC\uB77C\uC774\uBC84\uB97C \uC124\uCE58\uD569\uB2C8\uB2E4. \uC7AC\uBD80\uD305\uD558\uC9C0 \uC54A\uC73C\uBA74 \uC124\uCE58\uB41C \uAC83\uCC98\uB7FC \uBCF4\uC774\uC9C0\uB9CC \uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uC870\uC6A9\uD788 \uB3D9\uC791\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
            ["This Setup build is outdated"] = "\uC774 Setup \uBE4C\uB4DC\uB294 \uC624\uB798\uB418\uC5C8\uC2B5\uB2C8\uB2E4",
            ["This build can't be installed"] = "\uC774 \uBE4C\uB4DC\uB294 \uC124\uCE58\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
            ["This installs an OLDER version than the one installed."] = "\uC124\uCE58\uB41C \uAC83\uBCF4\uB2E4 \uC774\uC804 \uBC84\uC804\uC744 \uC124\uCE58\uD569\uB2C8\uB2E4.",
            ["This is a scaffold build without a bundled package, so there's nothing to install here. In a real setup bundle the .msix and .cer sit next to this exe."] = "\uC774 \uBE4C\uB4DC\uB294 \uD328\uD0A4\uC9C0\uAC00 \uD3EC\uD568\uB418\uC9C0 \uC54A\uC740 \uACE8\uACA9 \uBE4C\uB4DC\uB77C \uC124\uCE58\uD560 \uAC83\uC774 \uC5C6\uC2B5\uB2C8\uB2E4. \uC2E4\uC81C \uC124\uCE58 \uBC88\uB4E4\uC5D0\uC11C\uB294 .msix\uC640 .cer\uC774 \uC774 exe \uC606\uC5D0 \uC788\uC2B5\uB2C8\uB2E4.",
            ["This puts the device back and clears your ClawTweaks settings:"] = "\uAE30\uAE30\uB97C \uB418\uB3CC\uB9AC\uACE0 ClawTweaks \uC124\uC815\uC744 \uC9C0\uC6C1\uB2C8\uB2E4:",
            ["This removes ClawTweaks Center and closes it."] = "ClawTweaks Center\uB97C \uC81C\uAC70\uD558\uACE0 \uB2EB\uC2B5\uB2C8\uB2E4.",
            ["This removes the ClawTweaks app from Windows."] = "Windows\uC5D0\uC11C ClawTweaks \uC571\uC744 \uC81C\uAC70\uD569\uB2C8\uB2E4.",
            ["This resets ALL ClawTweaks settings to a clean state:"] = "\uBAA8\uB4E0 ClawTweaks \uC124\uC815\uC744 \uCD08\uAE30 \uC0C1\uD0DC\uB85C \uB418\uB3CC\uB9BD\uB2C8\uB2E4:",
            ["This takes a moment."] = "\uC7A0\uC2DC \uAC78\uB9BD\uB2C8\uB2E4.",
            ["This version can't be installed"] = "\uC774 \uBC84\uC804\uC740 \uC124\uCE58\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4",
            ["This version is already installed. Open it from the Start Menu or the ClawTweaks Game Bar widget instead of running this Setup file again."] = "\uC774 \uBC84\uC804\uC740 \uC774\uBBF8 \uC124\uCE58\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4. \uC774 \uC124\uCE58 \uD30C\uC77C\uC744 \uB2E4\uC2DC \uC2E4\uD589\uD558\uC9C0 \uB9D0\uACE0 \uC2DC\uC791 \uBA54\uB274\uB098 Game Bar\uC758 ClawTweaks \uC704\uC82F\uC5D0\uC11C \uC5EC\uC138\uC694.",
            ["Timed out"] = "\uC2DC\uAC04 \uCD08\uACFC",
            ["To tray"] = "\uD2B8\uB808\uC774\uB85C",
            ["Transition to new Center App - Uninstall the old version"] = "\uC0C8 Center\uB85C \uC804\uD658 \u2014 \uC774\uC804 \uBC84\uC804 \uC81C\uAC70",
            ["Trusts the signing certificate, installs the app package, opens the Game Bar and waits for the helper. Safe to run again on an update."] = "\uC11C\uBA85 \uC778\uC99D\uC11C\uB97C \uC2E0\uB8B0\uD558\uACE0 \uC571 \uD328\uD0A4\uC9C0\uB97C \uC124\uCE58\uD55C \uB4A4 Game Bar\uB97C \uC5F4\uACE0 \uD5EC\uD37C\uB97C \uAE30\uB2E4\uB9BD\uB2C8\uB2E4. \uC5C5\uB370\uC774\uD2B8 \uC2DC \uB2E4\uC2DC \uC2E4\uD589\uD574\uB3C4 \uC548\uC804\uD569\uB2C8\uB2E4.",
            ["Turn MSI Center M back on"] = "MSI Center M \uB2E4\uC2DC \uCF1C\uAE30",
            ["Turn it on in Onboarding. It switches itself back if no pad appears."] = "\uC628\uBCF4\uB529\uC5D0\uC11C \uCF1C\uC138\uC694. \uD328\uB4DC\uAC00 \uB098\uD0C0\uB098\uC9C0 \uC54A\uC73C\uBA74 \uC790\uB3D9\uC73C\uB85C \uB418\uB3CC\uB9BD\uB2C8\uB2E4.",
            ["Turn it on under Settings to show covers only."] = "\uC124\uC815\uC5D0\uC11C \uCF1C\uBA74 \uCEE4\uBC84\uB9CC \uD45C\uC2DC\uB429\uB2C8\uB2E4.",
            ["Turn on"] = "\uCF1C\uAE30",
            ["Turn on Settings \u2192 Start in the library to open here every time."] = "\uC124\uC815 \u2192 \uB77C\uC774\uBE0C\uB7EC\uB9AC\uB85C \uC2DC\uC791\uC744 \uCF1C\uBA74 \uD56D\uC0C1 \uC5EC\uAE30\uC11C \uC5F4\uB9BD\uB2C8\uB2E4.",
            ["Turning MSI Center M back on\u2026"] = "MSI Center M\uC744 \uB2E4\uC2DC \uCF1C\uB294 \uC911\u2026",
            ["Uninstall"] = "\uC81C\uAC70",
            ["Uninstall Center"] = "Center \uC81C\uAC70",
            ["Update ClawTweaks Center"] = "ClawTweaks Center \uC5C5\uB370\uC774\uD2B8",
            ["Update ClawTweaks from \"Update & Release\" first."] = "\uBA3C\uC800 \"Update & Release\"\uC5D0\uC11C ClawTweaks\uB97C \uC5C5\uB370\uC774\uD2B8\uD558\uC138\uC694.",
            ["Update failed \u2014 see the log for details. Try again, or run as Administrator."] = "\uC5C5\uB370\uC774\uD2B8 \uC2E4\uD328 \u2014 \uC790\uC138\uD55C \uB0B4\uC6A9\uC740 \uB85C\uADF8\uB97C \uBCF4\uC138\uC694. \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uAC70\uB098 \uAD00\uB9AC\uC790 \uAD8C\uD55C\uC73C\uB85C \uC2E4\uD589\uD558\uC138\uC694.",
            ["Updates cost no prompt \u2014 the task does not carry a version number."] = "\uC5C5\uB370\uC774\uD2B8\uC5D0\uB294 \uCC3D\uC774 \uB728\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC791\uC5C5\uC5D0 \uBC84\uC804 \uBC88\uD638\uAC00 \uC5C6\uAE30 \uB54C\uBB38\uC785\uB2C8\uB2E4.",
            ["Updating..."] = "\uC5C5\uB370\uC774\uD2B8 \uC911...",
            ["Use Uninstall ClawTweaks here in Center instead."] = "\uB300\uC2E0 Center\uC758 Uninstall ClawTweaks\uB97C \uC0AC\uC6A9\uD558\uC138\uC694.",
            ["Verifying the virtual pad\u2026"] = "\uAC00\uC0C1 \uD328\uB4DC \uD655\uC778 \uC911\u2026",
            ["Vibration"] = "\uC9C4\uB3D9",
            ["Virtual controller (VIIPER)"] = "\uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC (VIIPER)",
            ["Virtual controller already active \u2014 controller is healthy."] = "\uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uC774\uBBF8 \uD65C\uC131 \u2014 \uC0C1\uD0DC \uC591\uD638.",
            ["Virtual pad did not mount \u2014 rolling back to the hardware controller."] = "\uAC00\uC0C1 \uD328\uB4DC\uAC00 \uC62C\uB77C\uC624\uC9C0 \uC54A\uC544 \uD558\uB4DC\uC6E8\uC5B4 \uCEE8\uD2B8\uB864\uB7EC\uB85C \uB418\uB3CC\uB9BD\uB2C8\uB2E4.",
            ["Waiting for UAC\u2026"] = "UAC \uB300\uAE30 \uC911\u2026",
            ["Waiting for the ClawTweaks helper to start. If the Game Bar opened but nothing happens, select the ClawTweaks Widget in its widget menu and add it \u2014 a widget that isn't in the Game Bar yet doesn't start the helper on its own."] = "ClawTweaks \uD5EC\uD37C\uAC00 \uC2DC\uC791\uB420 \uB54C\uAE4C\uC9C0 \uAE30\uB2E4\uB9AC\uB294 \uC911\uC785\uB2C8\uB2E4. Game Bar\uAC00 \uC5F4\uB838\uC9C0\uB9CC \uC544\uBB34 \uC77C\uB3C4 \uC77C\uC5B4\uB098\uC9C0 \uC54A\uC73C\uBA74 \uC704\uC82F \uBA54\uB274\uC5D0\uC11C ClawTweaks \uC704\uC82F\uC744 \uC120\uD0DD\uD574 \uCD94\uAC00\uD558\uC138\uC694. Game Bar\uC5D0 \uC5C6\uB294 \uC704\uC82F\uC740 \uD5EC\uD37C\uB97C \uC2A4\uC2A4\uB85C \uC2DC\uC791\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
            ["Waiting for the ClawTweaks helper to start. If the Game Bar opened but nothing happens, select the ClawTweaks widget once."] = "ClawTweaks \uD5EC\uD37C\uAC00 \uC2DC\uC791\uB418\uAE30\uB97C \uAE30\uB2E4\uB9AC\uB294 \uC911\uC785\uB2C8\uB2E4. Game Bar\uAC00 \uC5F4\uB838\uB294\uB370 \uC544\uBB34 \uC77C\uB3C4 \uC5C6\uC73C\uBA74 ClawTweaks \uC704\uC82F\uC744 \uD55C \uBC88 \uC120\uD0DD\uD558\uC138\uC694.",
            ["Waiting for the virtual controller to settle\u2026"] = "\uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uC548\uC815\uB420 \uB54C\uAE4C\uC9C0 \uB300\uAE30 \uC911\u2026",
            ["What does the background helper do?"] = "\uBC31\uADF8\uB77C\uC6B4\uB4DC \uD5EC\uD37C\uB294 \uBB34\uC5C7\uC744 \uD558\uB098\uC694?",
            ["What happens"] = "\uBB34\uC5C7\uC774 \uC77C\uC5B4\uB098\uB294\uC9C0",
            ["What is the virtual controller for?"] = "\uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC\uB294 \uC65C \uD544\uC694\uD55C\uAC00\uC694?",
            ["What's new"] = "\uC0C8\uB85C\uC6B4 \uC810",
            ["Where are my settings, and how do I back them up?"] = "\uC124\uC815\uC740 \uC5B4\uB514\uC5D0 \uC788\uACE0, \uC5B4\uB5BB\uAC8C \uBC31\uC5C5\uD558\uB098\uC694?",
            ["Why does ClawTweaks ask for admin rights?"] = "ClawTweaks\uB294 \uC65C \uAD00\uB9AC\uC790 \uAD8C\uD55C\uC744 \uC694\uAD6C\uD558\uB098\uC694?",
            ["Wiki page"] = "\uC704\uD0A4 \uBB38\uC11C",
            ["Will be saved to"] = "\uC800\uC7A5 \uC704\uCE58",
            ["Windowed"] = "\uCC3D \uBAA8\uB4DC",
            ["Windows Insider Preview detected"] = "Windows Insider Preview \uAC10\uC9C0\uB428",
            ["Windows asked to uninstall Center. Finish here, or press B to keep everything."] = "Windows\uAC00 Center \uC81C\uAC70\uB97C \uC694\uCCAD\uD588\uC2B5\uB2C8\uB2E4. \uC5EC\uAE30\uC11C \uB9C8\uCE58\uAC70\uB098 B\uB97C \uB20C\uB7EC \uADF8\uB300\uB85C \uB450\uC138\uC694.",
            ["Windows could not open the package file. This is not a problem with the package itself \u2014 the deployment service (running as SYSTEM) could not read it. Try installing from a folder outside your user profile, and check whether Gaming Services is healthy."] = "Windows\uAC00 \uD328\uD0A4\uC9C0 \uD30C\uC77C\uC744 \uC5F4 \uC218 \uC5C6\uC5C8\uC2B5\uB2C8\uB2E4. \uD328\uD0A4\uC9C0 \uC790\uCCB4\uC758 \uBB38\uC81C\uAC00 \uC544\uB2C8\uB77C \u2014 \uBC30\uD3EC \uC11C\uBE44\uC2A4(SYSTEM \uAD8C\uD55C)\uAC00 \uC77D\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4. \uC0AC\uC6A9\uC790 \uD504\uB85C\uD544 \uBC16\uC758 \uD3F4\uB354\uC5D0\uC11C \uC124\uCE58\uD558\uACE0 Gaming Services \uC0C1\uD0DC\uB97C \uD655\uC778\uD558\uC138\uC694.",
            ["Windows could not open the package from this folder. Retrying from a machine-wide location\u2026"] = "Windows\uAC00 \uC774 \uD3F4\uB354\uC5D0\uC11C \uD328\uD0A4\uC9C0\uB97C \uC5F4 \uC218 \uC5C6\uC5C8\uC2B5\uB2C8\uB2E4. \uC2DC\uC2A4\uD15C \uC804\uC5ED \uC704\uCE58\uC5D0\uC11C \uB2E4\uC2DC \uC2DC\uB3C4\uD569\uB2C8\uB2E4\u2026",
            ["Windows file picker"] = "Windows \uD30C\uC77C \uC120\uD0DD\uAE30",
            ["Wipe every ClawTweaks setting back to a clean state (all profiles, fan curves, TDP, controller). This cannot be undone \u2014 take a backup first if unsure."] = "\uBAA8\uB4E0 ClawTweaks \uC124\uC815\uC744 \uCD08\uAE30 \uC0C1\uD0DC\uB85C \uB418\uB3CC\uB9BD\uB2C8\uB2E4 (\uD504\uB85C\uD544, \uD32C \uCEE4\uBE0C, TDP, \uCEE8\uD2B8\uB864\uB7EC). \uB418\uB3CC\uB9B4 \uC218 \uC5C6\uC73C\uB2C8 \uD655\uC2E4\uD558\uC9C0 \uC54A\uC73C\uBA74 \uBA3C\uC800 \uBC31\uC5C5\uD558\uC138\uC694.",
            ["Without it the gamepad still works, but those settings do nothing."] = "\uC5C6\uC5B4\uB3C4 \uAC8C\uC784\uD328\uB4DC\uB294 \uC791\uB3D9\uD558\uC9C0\uB9CC \uADF8 \uC124\uC815\uB4E4\uC740 \uC544\uBB34 \uD6A8\uACFC\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["Work down the list. Each step is optional except the last."] = "\uBAA9\uB85D\uC744 \uCC28\uB840\uB85C \uC9C4\uD589\uD558\uC138\uC694. \uB9C8\uC9C0\uB9C9 \uB2E8\uACC4\uB9CC \uD544\uC218\uC785\uB2C8\uB2E4.",
            ["Working\u2026"] = "\uC9C4\uD589 \uC911\u2026",
            ["XInput controllers"] = "XInput \uCEE8\uD2B8\uB864\uB7EC",
            ["Yes, if ClawTweaks should control the controller, the fan and the LEDs."] = "\uC608, ClawTweaks\uAC00 \uCEE8\uD2B8\uB864\uB7EC\uC640 \uD32C, LED\uB97C \uC81C\uC5B4\uD558\uB824\uBA74 \uD544\uC694\uD569\uB2C8\uB2E4.",
            ["Yes, if ClawTweaks should own the controller, the fan and the LEDs."] = "\uC608, ClawTweaks\uAC00 \uCEE8\uD2B8\uB864\uB7EC\uC640 \uD32C, LED\uB97C \uB9E1\uC544\uC57C \uD55C\uB2E4\uBA74\uC694.",
            ["Yes, install"] = "\uC608, \uC124\uCE58",
            ["Yes, reset everything"] = "\uC608, \uBAA8\uB450 \uCD08\uAE30\uD654",
            ["Yes, restore"] = "\uC608, \uBCF5\uC6D0",
            ["Yes, restore the device"] = "\uC608, \uAE30\uAE30\uB97C \uB418\uB3CC\uB9BD\uB2C8\uB2E4",
            ["Yes, uninstall Center"] = "\uC608, Center\uB97C \uC81C\uAC70\uD569\uB2C8\uB2E4",
            ["Yes, uninstall ClawTweaks"] = "\uC608, ClawTweaks\uB97C \uC81C\uAC70\uD569\uB2C8\uB2E4",
            ["Your Claw's own gamepad is hidden and replaced by a virtual one."] = "Claw\uC758 \uC2E4\uC81C \uAC8C\uC784\uD328\uB4DC\uB97C \uC228\uAE30\uACE0 \uAC00\uC0C1 \uAC8C\uC784\uD328\uB4DC\uB85C \uB300\uCCB4\uD569\uB2C8\uB2E4.",
            ["Your ClawTweaks library"] = "\uB0B4 ClawTweaks \uB77C\uC774\uBE0C\uB7EC\uB9AC",
            ["Your current settings are backed up before the reset. The Game Bar closes \u2014 reopen it with Win+G."] = "\uCD08\uAE30\uD654 \uC804\uC5D0 \uD604\uC7AC \uC124\uC815\uC744 \uBC31\uC5C5\uD569\uB2C8\uB2E4. \uAC8C\uC784 \uBC14\uAC00 \uB2EB\uD788\uB2C8 Win+G\uB85C \uB2E4\uC2DC \uC5EC\uC138\uC694.",
            ["Your games"] = "\uB0B4 \uAC8C\uC784",
            ["usbip  (required for virtual controller)"] = "usbip  (\uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC\uC5D0 \uD544\uC694)",
            ["version"] = "\uBC84\uC804",
            ["versions"] = "\uBC84\uC804",
            ["\u2022 All profiles, fan curves, TDP and controller settings are reset"] = "\u2022 \uBAA8\uB4E0 \uD504\uB85C\uD544, \uD32C \uCEE4\uBE0C, TDP, \uCEE8\uD2B8\uB864\uB7EC \uC124\uC815\uC774 \uCD08\uAE30\uD654\uB429\uB2C8\uB2E4",
            ["\u2022 Center's own settings are cleared"] = "\u2022 Center \uC790\uCCB4 \uC124\uC815\uC774 \uC9C0\uC6CC\uC9D1\uB2C8\uB2E4",
            ["\u2022 Global and per-game profiles (TDP, fan curves, controller, gyro)"] = "\u2022 \uC804\uC5ED \uBC0F \uAC8C\uC784\uBCC4 \uD504\uB85C\uD544 (TDP, \uD32C \uCEE4\uBE0C, \uCEE8\uD2B8\uB864\uB7EC, \uC790\uC774\uB85C)",
            ["\u2022 Helper settings (global TDP, fan curve, controller emulation)"] = "\u2022 \uD5EC\uD37C \uC124\uC815 (\uC804\uC5ED TDP, \uD32C \uCEE4\uBE0C, \uCEE8\uD2B8\uB864\uB7EC \uC5D0\uBBAC\uB808\uC774\uC158)",
            ["\u2022 The ClawTweaks app is NOT removed by this"] = "\u2022 ClawTweaks \uC571\uC740 \uC81C\uAC70\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4",
            ["\u2022 The Start Menu entry and the desktop shortcut go"] = "\u2022 \uC2DC\uC791 \uBA54\uB274 \uD56D\uBAA9\uACFC \uBC14\uD0D5 \uD654\uBA74 \uBC14\uB85C \uAC00\uAE30\uAC00 \uC0AC\uB77C\uC9D1\uB2C8\uB2E4",
            ["\u2022 The background helper stops and removes its scheduled task"] = "\u2022 \uBC31\uADF8\uB77C\uC6B4\uB4DC \uD5EC\uD37C\uAC00 \uBA48\uCD94\uACE0 \uC608\uC57D \uC791\uC5C5\uC744 \uC81C\uAC70\uD569\uB2C8\uB2E4",
            ["\u2022 The battery charge limit is switched off"] = "\u2022 \uBC30\uD130\uB9AC \uCDA9\uC804 \uC81C\uD55C\uC774 \uAEBC\uC9D1\uB2C8\uB2E4",
